// 导入文件读取和存在性判断方法
import { readFileSync, existsSync } from "fs";
// 导入路径拼接工具
import { join } from "path";

// A skill is a reusable prompt template in .mini-skills/<name>.md. Typing
// "/commit ..." loads it and runs its prompt (with any extra text appended) as
// if you'd typed the whole thing — install-and-use like a shell script.
// 技能（skill）是一个可复用的提示词模板，存放在 .mini-skills/<名称>.md 文件里。
// 输入 "/commit ..." 时会加载对应模板，并把后面附加的文字拼进去，整体当作提示词运行，
// 就像你亲手输入了全部内容一样 —— 类似 shell 脚本的"安装即用"。

// 技能文件存放目录：当前工作目录下的 .mini-skills 文件夹
const SKILLS_DIR = join(process.cwd(), ".mini-skills");

// 技能（skill）区域标记，供构建工具切片使用

// 解析用户输入是否触发了某个技能（以 "/" 开头）
// input —— 用户原始输入
// 返回解析后的完整提示词；若不是技能调用则返回 null
export function resolveSkill(input: string): string | null {
  // 不以 "/" 开头的输入不是技能调用，直接返回 null
  if (!input.startsWith("/")) return null;
  // 去掉 "/" 后按空格拆分：第一段是技能名，其余是附加参数
  const [name, ...rest] = input.slice(1).split(" ");
  // 拼出技能文件路径：.mini-skills/<技能名>.md
  const file = join(SKILLS_DIR, `${name}.md`);
  // 如果该技能文件不存在，返回 null（未匹配到技能）
  if (!existsSync(file)) return null;
  // 读取技能模板内容并去除首尾空白
  const prompt = readFileSync(file, "utf-8").trim();
  // 把附加参数重新拼成字符串
  const args = rest.join(" ").trim();
  // 如果有附加参数，拼到模板后面；否则只返回模板本身
  return args ? `${prompt}\n\n${args}` : prompt;
}

// 导入 Anthropic SDK（运行时使用）
import Anthropic from "@anthropic-ai/sdk";
// 导入工具执行函数和工具定义列表（来自本地工具模块）
import { executeTool, toolDefinitions } from "./tools.js";

// Fork a read-only sub-agent to investigate a task in its own fresh context and
// report back a concise summary — divide and conquer without pouring all the
// intermediate steps into the main conversation. It runs its own little loop,
// in-process, and only the summary comes back.
// 派生一个只读子 Agent，在它自己全新的上下文里去调查某个任务，
// 然后返回一段简洁的总结 —— 分而治之，且不会把所有中间步骤灌进主对话。
// 它在进程内运行自己的小循环，最终只把总结结果带回来。

// 子 Agent 允许使用的只读工具集合（只能看，不能改）
const EXPLORE_TOOLS = ["read_file", "list_files", "grep_search"];

// 子 Agent（subagent）区域标记，供构建工具切片使用

// 运行一个只读探索子 Agent
// task —— 交给子 Agent 的调查任务描述
// client —— Anthropic 客户端实例
// model —— 使用的模型名称
// 返回子 Agent 最终给出的文字总结
export async function runSubAgent(task: string, client: Anthropic, model: string): Promise<string> {
  // 子 Agent 的消息列表，初始只有用户下发的任务
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: task }];
  // 从全部工具定义中筛选出子 Agent 允许使用的只读工具
  const tools = toolDefinitions.filter((t) => EXPLORE_TOOLS.includes(t.name));

  // 子 Agent 自身的 ReAct 循环：不断调用模型，直到它不再请求工具
  while (true) {
    const reply = await client.messages.create({
      model, max_tokens: 4096,
      system: "You are an explore sub-agent. Investigate read-only and report back a concise summary.",
      tools, messages,
    });
    // 把模型回复加入消息历史
    messages.push({ role: "assistant", content: reply.content });

    // 从回复中筛出所有工具调用块（类型守卫确保类型正确）
    const toolUses = reply.content.filter((b): b is Anthropic.ToolUseBlock => b.type === "tool_use");
    // 如果模型没有再请求工具，说明调查完成，返回它的文字总结
    if (toolUses.length === 0) {
      return reply.content.filter((b) => b.type === "text").map((b: any) => b.text).join("");
    }
    // 收集每个工具调用的执行结果
    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const tu of toolUses) {
      // Read-only: a sub-agent can look but not touch.
      // 只读：子 Agent 只能看，不能改。

      // 只有允许的只读工具才真正执行；其他工具一律拒绝，返回拒绝提示
      const output = EXPLORE_TOOLS.includes(tu.name)
        ? await executeTool(tu.name, tu.input as Record<string, any>)
        : `Denied: the sub-agent is read-only.`;
      // 把工具结果封装成 tool_result 块，关联到对应的工具调用 id
      results.push({ type: "tool_result", tool_use_id: tu.id, content: output });
    }
    // 把工具结果作为 user 消息推入历史，供下一轮循环使用
    messages.push({ role: "user", content: results });
  }
}

// 导入子进程启动方法（用于把 MCP 服务器作为子进程运行）
import { spawn } from "child_process";
// 导入按行读取的接口（用于逐行解析子进程 stdout 输出的 JSON-RPC 消息）
import { createInterface } from "readline";

// A minimal MCP client: spawn the server as a subprocess and speak
// line-delimited JSON-RPC over its stdio — initialize, then discover its tools,
// then call them. Real MCP has more (multiple transports, auth); the stdio
// handshake is the essence, and it's how you plug external tools into the agent
// without changing its code.
// 一个最小化的 MCP 客户端：把服务器作为子进程启动，通过它的标准输入输出
// 以"按行分隔的 JSON-RPC"进行通信 —— 先初始化，再发现它提供的工具，然后调用。
// 真正的 MCP 功能更多（多种传输方式、鉴权等）；stdio 握手是其中最核心的部分，
// 这正是把外部工具接入 Agent 而无需改动 Agent 代码的方式。

// MCP 工具的描述结构：名称、描述、输入参数 schema
export interface McpTool { name: string; description: string; input_schema: unknown; }
// MCP 连接结构：可用的工具列表 + 调用工具的方法 + 关闭连接的方法
export interface McpConnection { tools: McpTool[]; callTool(name: string, args: unknown): Promise<string>; close(): void; }

// MCP 区域标记，供构建工具切片使用

// 连接一个 MCP 服务器：启动子进程，完成 JSON-RPC 握手，返回可用的工具和调用方法
// command —— 启动服务器的命令（如某个可执行程序）
// args —— 传给命令的参数数组
// 返回一个 McpConnection 对象
export async function connectMcp(command: string, args: string[]): Promise<McpConnection> {
  // 以子进程方式启动 MCP 服务器；stdin/stdout 用管道通信，stderr 直接继承到父进程
  const proc = spawn(command, args, { stdio: ["pipe", "pipe", "inherit"] });
  // 用 readline 逐行读取子进程的标准输出（每行是一个 JSON-RPC 消息）
  const rl = createInterface({ input: proc.stdout! });
  // 自增的请求 id，用于匹配请求与响应
  let nextId = 1;
  // 等待中的请求回调表：id -> resolve 函数
  const pending = new Map<number, (v: any) => void>();
  // 每收到一行就尝试解析为 JSON；若带有 id 且在等待表中，就触发对应的 resolve
  rl.on("line", (line) => {
    try { const msg = JSON.parse(line); if (msg.id && pending.has(msg.id)) { pending.get(msg.id)!(msg); pending.delete(msg.id); } } catch {}
  });
  // 发送一个 JSON-RPC 请求并返回 Promise，响应到达时 resolve
  const request = (method: string, params?: unknown) =>
    new Promise<any>((resolve) => {
      const id = nextId++;
      pending.set(id, resolve);
      // 把请求写成 JSON-RPC 格式写入子进程 stdin（末尾加换行符表示一行）
      proc.stdin!.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
    });

  // 1) 初始化握手：声明协议版本、能力、客户端信息
  await request("initialize", { protocolVersion: "2024-11-05", capabilities: {}, clientInfo: { name: "mini-claude", version: "1.0" } });
  // 2) 发送 initialized 通知（无需响应，所以没有 id）
  proc.stdin!.write(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }) + "\n");
  // 3) 列出服务器提供的所有工具
  const listed = await request("tools/list");
  // 把服务器返回的工具转换成本地使用的 McpTool 结构（注意 inputSchema -> input_schema 的命名映射）
  const tools: McpTool[] = (listed.result?.tools || []).map((t: any) => ({ name: t.name, description: t.description || "", input_schema: t.inputSchema }));

  // 返回连接对象，包含工具列表、调用工具方法、关闭方法
  return {
    tools,
    // 调用指定工具，返回其文本结果
    async callTool(name, args) {
      const r = await request("tools/call", { name, arguments: args });
      const content = r.result?.content || [];
      // 优先提取文本类型的内容；若没有文本则回退到整体 JSON 序列化
      return content.filter((c: any) => c.type === "text").map((c: any) => c.text).join("") || JSON.stringify(r.result ?? r.error);
    },
    // 关闭连接：直接杀掉子进程
    close() { proc.kill(); },
  };
}

